 view.innerHTML=page==='home'?renderHome():page==='explore'?renderExplore():page==='search'?renderSearch():page==='library'?renderLibrary():page==='liked'?renderLiked():page==='recent'?renderRecent():page==='local'?renderLocal():page==='upload'?renderUpload():page==='settings'?renderSettings():page.startsWith('playlist:')?renderPlaylist(page.split(':')[1]):heading('Sonic','Ready when you are.');
