 $$('[data-history-menu]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const wrap=b.closest('.history-action-wrap');$$('.history-action-wrap.open').forEach(w=>{if(w!==wrap){w.classList.remove('open');$('[data-history-menu]',w)?.setAttribute('aria-expanded','false');}});const open=wrap.classList.toggle('open');b.setAttribute('aria-expanded',String(open));}));
 $$('[data-history-remove]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();state.history=state.history.filter(t=>t.id!==b.dataset.historyRemove);save();renderView();toast('Removed from listening history');}));
 $('#clear-history')?.addEventListener('click',()=>{if(!state.history.length)return;state.history=[];save();renderView();toast('Listening history cleared');});
 $$('[data-play]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();const t=findTrack(b.dataset.play); if(t) playTrack(t);}));
 $$('[data-track]').forEach(el=>el.addEventListener('dblclick',()=>{const t=findTrack(el.dataset.track);if(t)playTrack(t);}));
