 $$('[data-queue]').forEach(b=>b.addEventListener('click',()=>queueTrack(findTrack(b.dataset.queue))));
 $$('[data-play-next]').forEach(b=>b.addEventListener('click',()=>queueTrack(findTrack(b.dataset.playNext),true)));
 $$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.searchFilter=b.dataset.filter;renderView();$('#search-page-input')?.focus();}));
 const si=$('#search-page-input'); if(si){si.addEventListener('input',()=>{state.search=si.value;const hasQuery=Boolean(si.value.trim());const clear=$('#search-clear');const enterHint=$('.search-enter-hint');if(clear)clear.hidden=!hasQuery;if(enterHint)enterHint.hidden=hasQuery;searchDebounced(si.value);});si.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchDebounced(si.value,{saveHistory:true});si.blur();}});}
 bindSearchHistoryControls();
 $('#search-clear')?.addEventListener('click',()=>{state.search='';state.searchResults=[];renderView();$('#search-page-input')?.focus();});
