 $$('[data-playlist-rename]').forEach(b=>b.addEventListener('click',()=>renamePlaylist(b.dataset.playlist)));
 $$('[data-playlist-delete]').forEach(b=>b.addEventListener('click',()=>deletePlaylist(b.dataset.playlist)));
